import{_ as l,o as n,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Per OSD Recovery Bandwidth Control Based on dmClock - Xie Xingguo & Yan Jun, ZTE Corporation","description":"","frontmatter":{"title":"Per OSD Recovery Bandwidth Control Based on dmClock - Xie Xingguo & Yan Jun, ZTE Corporation","date":"2019-05-24T00:00:00.000Z","updated":"2019-05-24T00:00:00.000Z","tags":["Ceph","bandwidth control","dmClock","recovery","distributed storage"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/Per_OSD_Recovery_Bandwidth_Control_Based_on_dmClock_-_Xie_Xingguo_Yan_Jun_ZTE_Corporation.md","filePath":"posts/2019/Per_OSD_Recovery_Bandwidth_Control_Based_on_dmClock_-_Xie_Xingguo_Yan_Jun_ZTE_Corporation.md","lastUpdated":1780459816000}'),i={name:"posts/2019/Per_OSD_Recovery_Bandwidth_Control_Based_on_dmClock_-_Xie_Xingguo_Yan_Jun_ZTE_Corporation.md"};function s(e,o,_,g,a,p){return n(),t("div",null,[...o[0]||(o[0]=[r('<p>Per OSD Recovery Bandwidth Control Based on dmClock的会议总结如下：</p><h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年某月某日</p><p><strong>会议地点</strong>： City Corporation</p><p><strong>参会人员</strong>： Hinging, She Single</p><p><strong>会议主题</strong>： 基于dmClock的存储去重方法设计、实现和测试</p><p><strong>会议内容</strong>：</p><p><strong>一、背景及问题</strong></p><ol><li><strong>背景</strong>： 存储去重对客户端性能有很大影响，但去重又是提高数据可靠性的必要手段。</li><li><strong>问题</strong>： 如何在保证数据可靠性的同时，尽量减少去重对客户端性能的影响。</li></ol><p><strong>二、解决方案</strong></p><ol><li><strong>主要思路</strong>： 通过控制去重操作的带宽，平衡去重与客户端性能之间的关系。</li><li><strong>核心方法</strong>： <ul><li>使用DM Clock进行带宽控制。</li><li>根据客户端性能要求，将去重操作分为三个级别：低、中、高。</li><li>根据负载状态，动态调整去重级别。</li></ul></li></ol><p><strong>三、DM Clock</strong></p><ol><li><strong>原理</strong>： 基于DM Clock进行带宽控制，类似于计算带宽预留。</li><li><strong>实现</strong>： <ul><li>DM Clock类和DM Clock客户端已集成到Ceph中。</li><li>基于DM Clock带宽计算公式，确定客户端目标带宽。</li><li>考虑其他服务完成的增量数据，进行带宽分配。</li></ul></li></ol><p><strong>四、去重操作实现</strong></p><ol><li><strong>OpIE类和DM Clock客户端</strong>： <ul><li>OpIE类被分为文件类型、去重、scrub和快照。</li><li>每个类型都有自己的QS参数，并使用多队列进行服务。</li></ul></li><li><strong>改进</strong>： <ul><li>引入新的DM Clock OpIE类，用于接收其他OSD发送的计数。</li><li>添加新的OpIE类型和Visual类，用于从其他OSD推送OpIE。</li><li>设置目标带宽，实现去重操作的带宽控制。</li></ul></li></ol><p><strong>五、负载状态与去重级别</strong></p><ol><li><strong>负载状态</strong>： 根据OSD的负载状态，将其分为四个级别：活跃、去重、恢复、重建。</li><li><strong>去重级别</strong>： 根据负载状态，将去重操作分为三个级别：低、中、高。</li></ol><p><strong>六、集群工作模式</strong></p><ol><li><strong>客户端优先级模式</strong>： 优先保证客户端性能，限制去重操作带宽。</li><li><strong>去重优先级模式</strong>： 优先完成去重操作，可能影响客户端性能。</li><li><strong>自适应模式</strong>： 根据负载状态，动态调整去重级别。</li></ol><p><strong>七、测试结果</strong></p><ol><li>测试环境：使用Ceph集群进行测试。</li><li>测试结果： <ul><li>在去重操作期间，客户端性能保持在10,000 IOPS左右。</li><li>去重操作完成时间为30分钟。</li><li>与其他模式相比，自适应模式在保证数据可靠性的同时，对客户端性能影响最小。</li></ul></li></ol><p><strong>八、后续行动计划</strong></p><ol><li>进一步优化DM Clock算法。</li><li>优化自适应模式，提高其性能。</li><li>在更多场景下进行测试，验证方案的有效性。</li></ol>',23)])])}const C=l(i,[["render",s]]);export{c as __pageData,C as default};
